// Общие функции шаблонов. Подключается из inc/_head.php.

// Адрес статического файла с меткой версии: браузер кэширует файл надолго,
// а после правки файла метка меняется и он скачивается заново.
function asset($path)
{
    $file = dirname(__DIR__) . $path;
    return $path . (is_file($file) ? '?v=' . filemtime($file) : '');
}

// <picture>: WebP для современных браузеров, исходный JPEG/PNG — запасной вариант для старых.
// $webp — адрес или готовый srcset; $attrs — остальные атрибуты <img> (alt, width, height, loading…).
function picture($webp, $fallback, $attrs, $sizes = '')
{
    return '<picture><source type="image/webp" srcset="' . $webp . '"' . ($sizes ? ' sizes="' . $sizes . '"' : '') . '>'
        . '<img src="' . $fallback . '" ' . $attrs . '></picture>';
}

